CREATE OR REPLACE FUNCTION app_private.guard_receipt_metadata()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare b jsonb;a jsonb;e jsonb:=app_private.receipt_effect();d jsonb;
begin
